<?php
namespace ZinCelestial\Platform\Audit;use RuntimeException;defined('ABSPATH')||exit;
interface WormStorageInterface{public function put_once(string $key,string $body,array $metadata):array;public function head(string $key):array;}
final class WormExportService{public function __construct(private \wpdb $db,private string $audit,private string $exports,private WormStorageInterface $storage,private int $site_id){}public function export(int $through_sequence,int $actor,string $approval):string{if($through_sequence<1||!preg_match('/^[A-Za-z0-9_-]{8,191}$/',$approval))throw new RuntimeException('Invalid export request.');$rows=$this->db->get_results($this->db->prepare("SELECT sequence_id,event,actor_id,key_id,payload,previous_hash,entry_hash,created_at FROM {$this->audit} WHERE site_id=%d AND sequence_id<=%d ORDER BY sequence_id",$this->site_id,$through_sequence),ARRAY_A);if(!$rows)throw new RuntimeException('No audit records to export.');$lines=[];foreach($rows as $r){ksort($r);$lines[]=wp_json_encode($r,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}$body=implode("\n",$lines)."\n";$digest=hash('sha256',$body);$id=wp_generate_uuid4();$key='audit/'.$this->site_id.'/'.$id.'.jsonl';$result=$this->storage->put_once($key,$body,['sha256'=>$digest,'site_id'=>(string)$this->site_id,'approval'=>$approval,'object_lock'=>'compliance']);if(($result['sha256']??'')!==$digest||empty($result['immutable']))throw new RuntimeException('WORM verification failed.');$ok=$this->db->insert($this->exports,['site_id'=>$this->site_id,'export_id'=>$id,'through_sequence'=>$through_sequence,'through_at'=>$rows[count($rows)-1]['created_at'],'object_key'=>$key,'manifest_hash'=>$digest,'verified'=>1,'verified_at'=>current_time('mysql',true),'created_at'=>current_time('mysql',true)]);if($ok!==1)throw new RuntimeException('Export registry append failed.');return$id;}}
